/* QRCode loader for site (shared)
 * Tries to load a local vendor copy, then CDN, then falls back to minimal client placeholder.
 * Provides a `QRCode` constructor when possible and a `makeQRCode(el, text, opts)` helper.
 */
(function(window, document){
	'use strict';

	function loadScript(src, onload, onerror) {
		var s = document.createElement('script');
		s.src = src;
		s.onload = onload || function(){};
		s.onerror = onerror || function(){};
		document.head.appendChild(s);
	}

	function ensureQRCode(callback) {
		if (window.QRCode) { return callback(); }

		// Try a shared global local copy first (/lib/js/qrcode.vendor.min.js)
		var globalLocal = (window.location && window.location.origin ? window.location.origin : '') + '/lib/js/qrcode.vendor.min.js';
		loadScript(globalLocal, function(){
			if (!window.QRCode) return tryCDN();
			// Validate the vendor implementation by trying a tiny sync render.
			try {
				var testDiv = document.createElement('div');
				// keep it off-document
				try { new window.QRCode(testDiv, {text: 'ok', width:16, height:16}); } catch(e){ return tryCDN(); }
				if (testDiv && testDiv.innerHTML && testDiv.innerHTML.trim()){
					return callback();
				}
			} catch(e){}
			tryCDN();
		}, tryCDN);

		function tryCDN(){
			var cdn = 'https://cdn.jsdelivr.net/npm/qrcodejs@1.0.0/qrcode.min.js';
			loadScript(cdn, function(){ if (window.QRCode) { callback(); } else finalFallback(); }, finalFallback);
		}

		function finalFallback(){
				window.QRCode = function(el, v) {
				if (typeof el === 'string') el = document.getElementById(el);
				if (!el) return;
				var opts = {};
				if (typeof v === 'object') { opts = v; }
				else { opts.text = v; }
				var container = el;
				container.innerHTML = '';
				var err = document.createElement('div');
				err.className = 'wifidb-qr-error';
				err.textContent = 'QR generation unavailable';
				container.appendChild(err);
			};
			window.QRCode.CorrectLevel = {L:0,M:1,Q:2,H:3};
			callback();
		}
	}

	window.makeQRCode = function(el, text, opts){
		ensureQRCode(function(){
			try {
				var container = (typeof el === 'string') ? document.getElementById(el) : el;
				if (!container) return;

				if (typeof window.QRCode === 'function'){
					var options = (opts && typeof opts === 'object') ? Object.assign({text: text}, opts) : {text: text};
					options.width = options.width || options.height || 128;
					options.height = options.height || options.width || 128;
					container.innerHTML = '';
					try { new window.QRCode(container, options); }
					catch(e){ tryAlternate(); }
					// Some vendor builds accept an options-only constructor and don't render
					// when passed (element, options). If the container is still empty, try alternate.
					try {
						if (container && (!container.innerHTML || !container.innerHTML.trim())) { tryAlternate(); }
					} catch(e) { /* ignore */ }

					function tryAlternate(){
						try {
							var inst = null;
							// Attempt: new QRCode(options)
							try { inst = new window.QRCode(options); } catch(e){ inst = null; }
							// Attempt: new QRCode()
							if (!inst){ try { inst = new window.QRCode(); } catch(e){ inst = null; } }
							// Attempt: new QRCode(container, options)
							if (!inst){ try { inst = new window.QRCode(container, options); } catch(e){ inst = null; } }
							if (!inst){ return failure(); }
							// Ensure instance points at container and has options
							try { inst._el = container; } catch(e){}
							try { inst._htOption = Object.assign((inst._htOption||{}), options||{}); } catch(e){}
							// Try calling makeCode
							if (typeof inst.makeCode === 'function'){
								try { inst.makeCode(options && options.text ? options.text : text); } catch(e){}
							} else {
								try { if (typeof inst._oQRCode !== 'undefined' && typeof inst._oQRCode.make === 'function') { inst._el = container; inst._oQRCode.make(); } } catch(e){}
							}
							var ok = container.innerHTML && container.innerHTML.trim() !== '';
							if (!ok) return failure();
							return;
						} catch(err){}
						failure();
					}

					function failure(){
						container.innerHTML = '';
						var err = document.createElement('div');
						err.className = 'wifidb-qr-error';
						err.textContent = 'QR generation unavailable';
						container.appendChild(err);
					}
					return;
				}

				new window.QRCode(container, {text: text, width: (opts && opts.width) ? opts.width : 128});
			} catch(e) {
				var container = (typeof el === 'string') ? document.getElementById(el) : el;
				if (!container) return;
				container.innerHTML = '';
				var err = document.createElement('div');
				err.className = 'wifidb-qr-error';
				err.textContent = 'QR generation unavailable';
				container.appendChild(err);
			}
		});
	};

})(window, document);
